import React, { useState } from 'react';
import { NavLink, useLocation } from 'react-router-dom';
import {
  Cpu,
  LayoutDashboard,
  Factory,
  Server,
  Radio,
  Sparkles,
  FlaskConical,
  Wrench,
  BarChart3,
  AlertTriangle,
  FileText,
  Settings,
  ChevronLeft,
  ChevronRight,
  Search,
  Activity,
  Database,
  CheckCircle2,
} from 'lucide-react';

const Sidebar = () => {
  const location = useLocation();
  const [collapsed, setCollapsed] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');

  // Primary Navigation Items
  const navItems = [
    {
      key: 'dashboard',
      title: 'Dashboard',
      icon: LayoutDashboard,
      path: '/',
      badge: 'Live',
    },
    {
      key: 'factoryOverview',
      title: 'Factory Overview',
      icon: Factory,
      path: '/plants',
      badge: '6 Plants',
    },
    {
      key: 'digitalTwin',
      title: 'Digital Twin',
      icon: Cpu,
      path: '/digital-twin',
      badge: '3D Sync',
    },
    {
      key: 'assetInventory',
      title: 'Asset Inventory',
      icon: Server,
      path: '/assets',
      badge: '20 Looms',
    },
    {
      key: 'sensorMonitoring',
      title: 'Sensor Monitoring',
      icon: Radio,
      path: '/sensors',
      badge: '136 Feeds',
    },
    {
      key: 'aiIntelligence',
      title: 'AI Intelligence',
      icon: Sparkles,
      path: '/ai-intelligence',
      badge: '99.4%',
    },
    {
      key: 'whatIfSimulator',
      title: 'What-If Simulator',
      icon: FlaskConical,
      path: '/what-if',
      badge: 'AI Lab',
    },
    {
      key: 'maintenanceCenter',
      title: 'Maintenance Center',
      icon: Wrench,
      path: '/maintenance',
      badge: '3 Orders',
    },
    {
      key: 'analytics',
      title: 'Analytics',
      icon: BarChart3,
      path: '/analytics',
      badge: '96.4% OEE',
    },
    {
      key: 'alerts',
      title: 'Alerts',
      icon: AlertTriangle,
      path: '/alerts',
      badge: '3 Active',
    },
    {
      key: 'reports',
      title: 'Reports',
      icon: FileText,
      path: '/reports',
    },
    {
      key: 'settings',
      title: 'Settings',
      icon: Settings,
      path: '/settings',
    },
  ];

  // Filter items if user types in search box
  const filteredItems = navItems.filter((item) =>
    item.title.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <aside className={`sidebar ${collapsed ? 'collapsed' : ''}`}>
      {/* Sidebar Header Brand Logo */}
      <div className="sidebar-brand">
        <div className="brand-icon-box">
          <Cpu size={22} />
        </div>
        {!collapsed && (
          <div className="brand-text-group">
            <span className="brand-title">TexTwin</span>
            <span className="brand-badge">Digital Twin OS</span>
          </div>
        )}
      </div>

      {/* Search Bar Input */}
      {!collapsed && (
        <div className="sidebar-search-box">
          <Search size={14} className="sidebar-search-icon" />
          <input
            type="text"
            className="sidebar-search-input"
            placeholder="Search navigation..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
          />
        </div>
      )}

      {/* Navigation List */}
      <nav className="sidebar-nav">
        {filteredItems.map((item) => {
          const Icon = item.icon;
          const isItemActive = location.pathname === item.path;

          return (
            <NavLink
              key={item.key}
              to={item.path}
              className={() => `sidebar-link ${isItemActive ? 'active' : ''}`}
              title={item.title}
              end={item.path === '/'}
              style={{ display: 'flex', alignItems: 'center', gap: '0.65rem' }}
            >
              <Icon size={20} style={{ flexShrink: 0, minWidth: '20px' }} />
              {!collapsed && (
                <div style={{ flex: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center', overflow: 'hidden' }}>
                  <span className="sidebar-link-text" style={{ whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis', fontWeight: '700' }}>
                    {item.title}
                  </span>
                  {item.badge && (
                    <span className="sidebar-mini-badge" style={{ flexShrink: 0, marginLeft: '6px', whiteSpace: 'nowrap' }}>
                      {item.badge}
                    </span>
                  )}
                </div>
              )}
            </NavLink>
          );
        })}
      </nav>

      {/* Section 14: Bottom Sidebar System Status Widget */}
      {!collapsed && (
        <div className="sidebar-status-box" style={{ background: 'var(--bg-primary)', border: '1px solid var(--border-subtle)', borderRadius: 'var(--radius-sm)', padding: '0.85rem', margin: '0.75rem' }}>
          <div style={{ fontSize: '0.74rem', fontWeight: '800', color: 'var(--text-primary)', display: 'flex', alignItems: 'center', gap: '0.4rem', marginBottom: '0.5rem' }}>
            <Activity size={15} style={{ color: 'var(--status-running)' }} />
            <span>SYSTEM HEALTH STATUS</span>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '0.3rem', fontSize: '0.7rem', color: 'var(--text-secondary)' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>MongoDB:</span>
              <span style={{ color: 'var(--status-running)', fontWeight: '800' }}>🟢 Connected</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>AI Engine:</span>
              <span style={{ color: 'var(--status-running)', fontWeight: '800' }}>🟢 Running</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>MQTT Broker:</span>
              <span style={{ color: 'var(--status-running)', fontWeight: '800' }}>🟢 Connected</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between' }}>
              <span>REST API:</span>
              <span style={{ color: 'var(--status-running)', fontWeight: '800' }}>🟢 Online</span>
            </div>
          </div>
        </div>
      )}

      {/* Collapse/Expand Sidebar Trigger Button */}
      <button
        className="sidebar-toggle-btn"
        onClick={() => setCollapsed(!collapsed)}
        title={collapsed ? 'Expand Sidebar Menu' : 'Collapse Sidebar Menu'}
      >
        {collapsed ? <ChevronRight size={18} /> : <ChevronLeft size={18} />}
      </button>
    </aside>
  );
};

export default Sidebar;
